value.expr:
(
 $s := $state.calc;
 $k := $event;
 $initial := {"display":"0","acc":null,"op":null,"fresh":true,"error":null,"formula":""};
 $digit := $contains('0123456789', $k) and $length($k)=1;
 $num := function($v){$number($v)};
 $fmt := function($v){$string($round($v,10))};
 $apply := function($a,$b,$op){$op='+' ? $a+$b : $op='-' ? $a-$b : $op='*' ? $a*$b : $a/$b};
 $operator := $k in ['+','-','*','/'];
 $base := $s.error ? $initial : $s;
 $d := $base.display;
 $input := $digit or $k='.';
 $rhs := $num($s.display);
 $pending := $s.op != null and $not($s.fresh);
 $zero := $pending and $s.op='/' and $rhs=0;
 $result := $zero ? 0 : ($pending ? $apply($s.acc,$rhs,$s.op) : $rhs);
 $k='C' ? $initial :
 $input ? $merge([$base, {"display": $k='.' ? ($base.fresh ? '0.' : ($contains($d,'.') ? $d : $d & '.')) : ($base.fresh or $d='0' ? $k : $d='-0' ? '-' & $k : $d & $k), "fresh":false,"error":null,"formula":$base.fresh and $base.op=null ? '' : $base.formula}]) :
 $s.error ? $s :
 $k='Backspace' ? ($s.fresh ? $s : $merge([$s,{"display":$length($d)<=1 or ($length($d)=2 and $substring($d,0,1)='-') ? '0' : $substring($d,0,$length($d)-1)}])) :
 $k='%' ? $merge([$s,{"display":$fmt($num($d)/100),"fresh":false}]) :
 $k='sign' ? $merge([$s,{"display":$substring($d,0,1)='-' ? $substring($d,1) : '-' & $d,"fresh":false}]) :
 ($operator or $k='=') ? (
 $zero ? $merge([$s,{"error":"0으로 나눌 수 없습니다","fresh":true}]) :
 $operator ? {"display":$fmt($result),"acc":$result,"op":$k,"fresh":true,"error":null,"formula":$fmt($result)&' '&$k} :
 $pending ? {"display":$fmt($result),"acc":null,"op":null,"fresh":true,"error":null,"formula":$fmt($s.acc)&' '&$s.op&' '&$s.display&' ='} : $s
 ) : $s
)
